import{_ as f,c as r,o as i,j as a,a8 as t,t as s,a as n}from"./chunks/framework.C_eYonIk.js";const q=JSON.parse('{"title":"读书的人 - 读书笔记","description":"","frontmatter":{"title":"读书的人 - 读书笔记","outline":[2,2],"finishedDate":"2025-10-16"},"headers":[],"relativePath":"blog/read/books/读书的人.md","filePath":"blog/read/books/读书的人.md","lastUpdated":1795017144000}'),v={name:"blog/read/books/读书的人.md"},p={class:"social-psychology-notes"},l={class:"reading-book","aria-label":"书籍信息"},c={class:"reading-book-info"},o={class:"reading-metadata"},u=["datetime"];function b(d,e,g,x,k,h){return i(),r("div",null,[a("div",p,[e[8]||(e[8]=a("header",{class:"reading-header"},[a("h1",null,"读书的人"),a("p",{class:"reading-byline"},"作者：魏小河"),a("div",{class:"reading-stats"},[a("span",null,"23 条摘抄"),a("span",null,"3 则随想"),a("span",null,"微信读书")])],-1)),a("section",l,[e[7]||(e[7]=a("div",{class:"reading-cover"},[a("img",{src:"https://cdn.weread.qq.com/weread/cover/50/cpplatform_hydcqkmzixddhjsua2dekn/t6_cpplatform_hydcqkmzixddhjsua2dekn1728631192.jpg",alt:"读书的人封面",width:"160",loading:"lazy"})],-1)),a("div",c,[e[4]||(e[4]=a("p",{class:"reading-book-title"},"书籍信息",-1)),a("dl",o,[e[1]||(e[1]=t("<div data-v-568ffe19><dt data-v-568ffe19>书名</dt><dd data-v-568ffe19>读书的人</dd></div><div data-v-568ffe19><dt data-v-568ffe19>作者</dt><dd data-v-568ffe19>魏小河</dd></div><div data-v-568ffe19><dt data-v-568ffe19>出版社</dt><dd data-v-568ffe19>浙江文艺出版社有限公司</dd></div><div data-v-568ffe19><dt data-v-568ffe19>出版时间</dt><dd data-v-568ffe19>2024-08-01 00:00:00</dd></div>",4)),a("div",null,[e[0]||(e[0]=a("dt",null,"完读日期",-1)),a("dd",null,[a("time",{datetime:d.$frontmatter.finishedDate},s(d.$frontmatter.finishedDate),9,u)])]),e[2]||(e[2]=a("div",null,[a("dt",null,"ISBN"),a("dd",null,"9787533976552")],-1)),e[3]||(e[3]=a("div",null,[a("dt",null,"分类"),a("dd",null,"文学-散文杂著")],-1))]),e[5]||(e[5]=a("a",{class:"reading-original-link",href:"https://weread.qq.com/web/reader/cc532280813ab944cg01083d",target:"_blank",rel:"noopener noreferrer"},[n("在微信读书中打开 "),a("span",{"aria-hidden":"true"},"↗")],-1)),e[6]||(e[6]=a("details",{class:"reading-description"},[a("summary",null,"书籍简介"),a("p",null,"《读书的人》是90后青年书评人魏小河的最新作品集，也是一次随书而行的旅途。本书分为“星辰时刻”“多元世界的可能”“汉语的一种风度”“生活在他处”四辑，共收录34篇文章。从裂着口的严冬大地出发，走到萧红的陨落，张爱玲在前半生的逼仄中引来时代的序曲，整个星辰时刻无一不是普通人的一生；翻开一本科幻小说，或是道德小说，触摸自由意志和爱的搏杀、离开和留下的拉扯，感受多元世界的可能和汉语的一种风度；读书的人，最需要的是投入世界的热情和改变世界的勇气，到了旅程的末梢，我们进入游荡者的世界——既有关于旅行的无限清单，也有深入非洲、中亚腹地的神奇经历，还有生活在东京八平米、英国民间的经验观察。")],-1))])]),e[9]||(e[9]=t('<h2 id="星辰时刻" tabindex="-1" data-v-568ffe19>星辰时刻 <a class="header-anchor" href="#星辰时刻" aria-label="Permalink to “星辰时刻”" data-v-568ffe19>​</a></h2><blockquote class="reading-excerpt" id="excerpt-001" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>001</span><div data-v-568ffe19><p data-v-568ffe19>残忍而不知残忍，荒诞而不知荒诞。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-002" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>002</span><div data-v-568ffe19><p data-v-568ffe19>旧生活瓦解，卡在中间的人，很容易折断。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-003" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>003</span><div data-v-568ffe19><p data-v-568ffe19>我恰好也成长于工人阶级家庭，并且，也成长于一个变动的时代。巨大的城市化浪潮，把很多像我一样的人卷入了新的进程。许多人都面对着这样一组横亘在家庭和社会、过去和未来之间的矛盾。这种处境，好像只有在流动中的人才能感同身受，如果一直处于稳固的系统中，面对的就是另一种境遇。</p></div></blockquote><aside class="reading-thought" aria-label="个人随想" data-v-568ffe19><div class="reading-thought-meta" data-v-568ffe19><span data-v-568ffe19>我的随想</span><time datetime="2025-09-26" data-v-568ffe19>2025/09/26</time></div><p data-v-568ffe19>流动中的人，我挺喜欢这个形容的，读大学的时候第一次离家，去了很远的兰州。<br data-v-568ffe19>我一直都特别清楚的记得，坐在成都去往兰州的火车上，我哭的多厉害，不管旁人眼光，自己在那哭得昏天黑地，桌子上堆起一个高高的小山丘。<br data-v-568ffe19>四年往返于兰州跟攀枝花，成都是中转站。<br data-v-568ffe19>毕业之后偶然的机会去了上海，因为工作又辗转武汉，内蒙古，北京，上海，在这过程中昆明是中转站。<br data-v-568ffe19>因为换工作，呆在昆明，后面往返昆明跟攀枝花，没有中转站。<br data-v-568ffe19>经济情况不好，又离开昆明，来到广州，往后昆明又是中转站。<br data-v-568ffe19>我不以自己辗转那么多城市感到居无定所，每次从不熟悉到熟悉这个适应过程确实会觉得孤单，但后面结束这段旅行的时候，都会有一些可以往来的朋友，<br data-v-568ffe19>对这些城市也有独一份的记忆，遇到的人，发生的事，这座城市的风景，人文，这些也只有流动的人才能感受到的。<br data-v-568ffe19>现在这个时代背景下，像我这样的人不在少数，挺好，我们并不是一个少数群体，而是大多数。</p><blockquote class="reading-thought-source" data-v-568ffe19><p class="reading-source-label" data-v-568ffe19>对应原文</p><p data-v-568ffe19>我恰好也成长于工人阶级家庭，并且，也成长于一个变动的时代。巨大的城市化浪潮，把很多像我一样的人卷入了新的进程。许多人都面对着这样一组横亘在家庭和社会、过去和未来之间的矛盾。这种处境，好像只有在流动中的人才能感同身受，如果一直处于稳固的系统中，面对的就是另一种境遇。</p></blockquote></aside><blockquote class="reading-excerpt" id="excerpt-004" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>004</span><div data-v-568ffe19><p data-v-568ffe19>我们每个人的生活都是值得书写的</p></div></blockquote><h2 id="多元世界的可能" tabindex="-1" data-v-568ffe19>多元世界的可能 <a class="header-anchor" href="#多元世界的可能" aria-label="Permalink to “多元世界的可能”" data-v-568ffe19>​</a></h2><blockquote class="reading-excerpt" id="excerpt-005" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>005</span><div data-v-568ffe19><p data-v-568ffe19>一开始我就知道结局，我选定了自己要走的路，也就是未来的必经之路。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-006" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>006</span><div data-v-568ffe19><p data-v-568ffe19>即使一切是预定的，那也只有你去实践了，才真正算数。就算已经预知了终点，也要充分体验每一个瞬间</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-007" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>007</span><div data-v-568ffe19><p data-v-568ffe19>有些事情成了你的一部分，不是那么容易换的”</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-008" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>008</span><div data-v-568ffe19><p data-v-568ffe19>人对于低于自己的人，不只有同情，甚至有一种恶作剧式的嘲弄。这种奇怪的心理，是芥川龙之介很感兴趣的。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-009" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>009</span><div data-v-568ffe19><p data-v-568ffe19>故事关于不死之人，我们都是不死之人，这倒不是因为我们真的不会死，而是会有一个和我们很像的人接替我们，就像轮回，但又不是轮回，并不是我们死了然后投胎，而可能是我没有死，就已经有另一个我出现。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-010" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>010</span><div data-v-568ffe19><p data-v-568ffe19>不论是庸常的无聊的相似的人生，还是清醒的独一无二的拥有自由的人生，都是很难承受的</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-011" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>011</span><div data-v-568ffe19><p data-v-568ffe19>第一种是这个AI觉醒了，不论他是机器人还是生化人，他有了自我意识，他开始思考自我的存在、需求和尊严。此时，我们该如何看待他？如何看待他的权利？往往，这一设定是为了引发人对自身的反思，到底什么构成了人的尊严和人不可让渡的东西？<br data-v-568ffe19>第二种则是这个AI没有觉醒，他尽职尽责完成自己的使命</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-012" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>012</span><div data-v-568ffe19><p data-v-568ffe19>最终，克拉拉被抛弃了。她像一个见证者，我们通过她的视角，看到了人心的复杂。人会后悔，会踌躇，会迟疑，会猜忌，会嫉妒，会伤心，会痛苦，会爱，同时，也会遗忘，会告别。这里面没有审判，而是一种理解，或者说不理解。我们不知道这样的人类，会将自己送上怎样的道路。</p></div></blockquote><h2 id="汉语的一种风度" tabindex="-1" data-v-568ffe19>汉语的一种风度 <a class="header-anchor" href="#汉语的一种风度" aria-label="Permalink to “汉语的一种风度”" data-v-568ffe19>​</a></h2><blockquote class="reading-excerpt" id="excerpt-013" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>013</span><div data-v-568ffe19><p data-v-568ffe19>我们站在森林的入口，并不往里走，而是心满意足地转身离去。有一种说不出的意蕴，好像人生中的所有灰，都藏在那里了一样。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-014" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>014</span><div data-v-568ffe19><p data-v-568ffe19>这不是绝望的，我们知道，一切都会过去。但这一段生活，也值得被记录。它是那种晃荡和不定的日子，也是每个人的生活中都会有的游离时刻。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-015" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>015</span><div data-v-568ffe19><p data-v-568ffe19>都市里，人们摩肩接踵却互不相知，地铁上一眼望去那么多人，一到站，轰地散开，每个人身上都有秘密。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-016" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>016</span><div data-v-568ffe19><p data-v-568ffe19>“别人身上的苦头，尝起来舌根甘甜”</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-017" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>017</span><div data-v-568ffe19><p data-v-568ffe19>&gt; 原文：一部电影《阳光普照》，里面的儿子也突然自杀了，说不清楚原因，成为家里的一个洞。无论如何，剩下的人，要带着这个洞活下去。<br data-v-568ffe19>```<br data-v-568ffe19>2025/10/08发表想法<br data-v-568ffe19>阳光普照里面的大儿子的自杀并不突然，长期承受了太多父母的期待，是一种过于沉重的负担，就像电影里面大儿子自己说的，他无处躲藏。<br data-v-568ffe19>一直在父母的期待下生活，看似听话，懂事，内心却很压抑…<br data-v-568ffe19>```</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-018" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>018</span><div data-v-568ffe19><p data-v-568ffe19>人这一生，很多事情说不清楚，遇上了就遇上了，就算生离死别，也没有办法，只能承受。但如何去承受，如何去面对，里面有很多无奈，也有尊严，和人之所以为人的东西。它们琐屑，却也发光。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-019" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>019</span><div data-v-568ffe19><p data-v-568ffe19>并不一定经历得多就能写得好，但生活永远是写作最好的老师</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-020" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>020</span><div data-v-568ffe19><p data-v-568ffe19>&gt; 原文：突然间好羡慕除我之外的世上所有的人，隔壁的职工，村里的酒鬼，甚至是我家雇佣的短工。他们生活稳定有序，行事从容不迫。<br data-v-568ffe19>```<br data-v-568ffe19>2025/10/11发表想法<br data-v-568ffe19>好长好长一段时间我自己也是这么想的，我希望自己是任何人都好，只要不是自己…那段时间很糟糕，很自卑，感觉自己做什么都是错…<br data-v-568ffe19>```</p></div></blockquote><aside class="reading-thought" aria-label="个人随想" data-v-568ffe19><div class="reading-thought-meta" data-v-568ffe19><span data-v-568ffe19>我的随想</span><time datetime="2025-10-08" data-v-568ffe19>2025/10/08</time></div><p data-v-568ffe19>阳光普照里面的大儿子的自杀并不突然，长期承受了太多父母的期待，是一种过于沉重的负担，就像电影里面大儿子自己说的，他无处躲藏。一直在父母的期待下生活，看似听话，懂事，内心却很压抑…</p><blockquote class="reading-thought-source" data-v-568ffe19><p class="reading-source-label" data-v-568ffe19>对应原文</p><p data-v-568ffe19>一部电影《阳光普照》，里面的儿子也突然自杀了，说不清楚原因，成为家里的一个洞。无论如何，剩下的人，要带着这个洞活下去。</p></blockquote></aside><aside class="reading-thought" aria-label="个人随想" data-v-568ffe19><div class="reading-thought-meta" data-v-568ffe19><span data-v-568ffe19>我的随想</span><time datetime="2025-10-11" data-v-568ffe19>2025/10/11</time></div><p data-v-568ffe19>好长好长一段时间我自己也是这么想的，我希望自己是任何人都好，只要不是自己…那段时间很糟糕，很自卑，感觉自己做什么都是错…</p><blockquote class="reading-thought-source" data-v-568ffe19><p class="reading-source-label" data-v-568ffe19>对应原文</p><p data-v-568ffe19>突然间好羡慕除我之外的世上所有的人，隔壁的职工，村里的酒鬼，甚至是我家雇佣的短工。他们生活稳定有序，行事从容不迫。</p></blockquote></aside><h2 id="生活在别处" tabindex="-1" data-v-568ffe19>生活在别处 <a class="header-anchor" href="#生活在别处" aria-label="Permalink to “生活在别处”" data-v-568ffe19>​</a></h2><blockquote class="reading-excerpt" id="excerpt-021" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>021</span><div data-v-568ffe19><p data-v-568ffe19>按照保罗·索鲁的定义，这算不上一场真正的旅行。我更像是他笔下不遗余力讽刺的观光客：手中带着攻略，一路奔向目的地，体验早已预设好的体验，然后离开，从未深度介入，只是观看和消费</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-022" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>022</span><div data-v-568ffe19><p data-v-568ffe19>在这个时代，只要你想，几乎可以去到世界上的任何地方。但是，我们的经验却越来越相似，越来越贫乏。我们总是去那些热门的景点打卡，去被标记为五星的餐厅吃饭，我们不再相信偶然，不再闯入未知，一切都发生在巨大的网络之中，安全且无聊。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-023" data-v-568ffe19><span class="reading-excerpt-number" aria-hidden="true" data-v-568ffe19>023</span><div data-v-568ffe19><p data-v-568ffe19>阅读保罗·索鲁是愉快的，但我很快发现，游记几乎已经是一个濒临绝种的文体。在书店“旅游”标识的书架下，根本找不到几本真正的游记。放眼望去，要么是攻略书，要么就是打着旅行旗号的心灵鸡汤或故事会。那种给人深刻浸入感的游记，少之又少。一方面，当然是因为这个世界再也没有未竟之地；另一方面，或许还在于许多人都抛弃了文字。随着新媒体的发展，互联网上诞生了许多旅行博主，他们穿着光鲜华服，出现在世界各地的景点、酒店。他们制造了一种幻想，一种永远生活在别处，耀眼、明亮、五彩缤纷的生活。</p></div></blockquote><footer class="reading-footer" data-v-568ffe19><span data-v-568ffe19>书籍来源：微信读书</span><span data-v-568ffe19>整理时间：2025年</span></footer>',31))])])}const _=f(v,[["render",b],["__scopeId","data-v-568ffe19"]]);export{q as __pageData,_ as default};
